<form class="admin-order-filter" method="get"><input type="hidden" name="r" value="admin/orders"><input class="form-control" name="q" placeholder="Order, customer or mobile" value="<?= e($_GET['q']??'') ?>" aria-label="Search orders"><select name="status" class="form-select" aria-label="Order status"><option value="">All order statuses</option><?php foreach($orderStatuses as $s): ?><option <?= ($_GET['status']??'')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select><select class="form-select" name="payment_status" aria-label="Payment status"><option value="">All payments</option><?php foreach(['pending','paid','failed','refunded'] as $s): ?><option <?= ($_GET['payment_status']??'')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select><input class="form-control" type="date" name="from" value="<?= e($_GET['from']??'') ?>" aria-label="Start date"><input class="form-control" type="date" name="to" value="<?= e($_GET['to']??'') ?>" aria-label="End date"><button class="btn btn-primary">Filter</button></form><section class="panel table-panel"><?php require ROOT.'/app/Views/admin/order-table.php'; ?></section><div class="pagination-row"><?php $page=max(1,(int)($_GET['page']??1));if($page>1): ?><a href="<?= e(url('admin/orders',array_merge($_GET,['page'=>$page-1]))) ?>">← Previous</a><?php endif ?><span>Page <?= $page ?></span><?php if(count($orders)===30): ?><a href="<?= e(url('admin/orders',array_merge($_GET,['page'=>$page+1]))) ?>">Next →</a><?php endif ?></div>
